package gen

import (
	"fmt"
	"strings"
)

// runtimeImportPath is the import path of the runtime package used by
// all generated code. It could be parameterized later (e.g. vendoring),
// but for now it is fixed.
const runtimeImportPath = "github.com/rodrigocelsius/go-nitro/json/runtime/v2"

// Generate produces the full Go source (including package declaration
// and imports) for AppendJSON/ParseJSON of every struct in defs.
// packageName is the package of the generated file (must match the
// package where the original structs live).
func Generate(packageName string, defs []StructDef) (string, error) {
	var b strings.Builder

	fmt.Fprintf(&b, "// Code generated by nitro/json/gen. DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", packageName)

	// Check if any field uses time.Time
	needsTime := false
	for _, def := range defs {
		for _, f := range def.Fields {
			if f.Kind == KindTime || (f.Kind == KindSlice && f.ElemKind == KindTime) || (f.Kind == KindMap && f.ElemKind == KindTime) {
				needsTime = true
				break
			}
		}
		if needsTime {
			break
		}
	}

	if needsTime {
		fmt.Fprintf(&b, "import (\n\t\"strconv\"\n\t\"time\"\n\n\tjsonrt %q\n)\n\n", runtimeImportPath)
	} else {
		fmt.Fprintf(&b, "import (\n\t\"strconv\"\n\n\tjsonrt %q\n)\n\n", runtimeImportPath)
	}

	for _, def := range defs {
		if len(def.Fields) == 0 {
			continue // struct with no json-tagged fields; nothing to generate
		}
		marshalCode, err := generateMarshal(def)
		if err != nil {
			return "", fmt.Errorf("gen: marshal for %s: %w", def.Name, err)
		}
		b.WriteString(marshalCode)
		b.WriteString("\n")

		unmarshalCode, err := generateUnmarshal(def)
		if err != nil {
			return "", fmt.Errorf("gen: unmarshal for %s: %w", def.Name, err)
		}
		b.WriteString(unmarshalCode)
		b.WriteString("\n")
	}

	return b.String(), nil
}

// generateMarshal produces AppendJSON for a struct, writing JSON
// directly into a reusable []byte (no new buffer allocation — the
// caller chooses the buffer, matching the pattern validated in
// user_manual.go/BenchmarkManual_Marshal).
func generateMarshal(def StructDef) (string, error) {
	var b strings.Builder
	fmt.Fprintf(&b, "func (v *%s) AppendJSON(buf []byte) []byte {\n", def.Name)
	b.WriteString("\tbuf = append(buf, '{')\n")

	for i, f := range def.Fields {
		if i > 0 {
			b.WriteString("\tbuf = append(buf, ',')\n")
		}
		fmt.Fprintf(&b, "\tbuf = append(buf, %q...)\n", `"`+f.JSONName+`":`)

		code, err := marshalFieldCode(f)
		if err != nil {
			return "", err
		}
		b.WriteString(code)
	}

	b.WriteString("\tbuf = append(buf, '}')\n")
	b.WriteString("\treturn buf\n")
	b.WriteString("}\n")
	return b.String(), nil
}

func marshalFieldCode(f Field) (string, error) {
	access := "v." + f.GoName
	switch f.Kind {
	case KindString:
		return fmt.Sprintf("\tbuf = append(buf, '\"')\n\tbuf = jsonrt.AppendJSONEscapedString(buf, %s)\n\tbuf = append(buf, '\"')\n", access), nil
	case KindInt:
		return fmt.Sprintf("\tbuf = strconv.AppendInt(buf, int64(%s), 10)\n", access), nil
	case KindFloat:
		return fmt.Sprintf("\tbuf = strconv.AppendFloat(buf, float64(%s), 'f', -1, 64)\n", access), nil
	case KindBool:
		return fmt.Sprintf("\tbuf = strconv.AppendBool(buf, %s)\n", access), nil
	case KindStruct:
		return fmt.Sprintf("\tbuf = (&%s).AppendJSON(buf)\n", access), nil
	case KindStructPtr:
		return fmt.Sprintf("\tif %s == nil {\n\t\tbuf = append(buf, \"null\"...)\n\t} else {\n\t\tbuf = %s.AppendJSON(buf)\n\t}\n", access, access), nil
	case KindSlice:
		return marshalSliceCode(f, access)
	case KindMap:
		return marshalMapCode(f, access)
	case KindTime:
		return fmt.Sprintf("\tbuf = append(buf, '\"')\n\tbuf = append(buf, %s.Format(\"2006-01-02T15:04:05Z07:00\")...)\n\tbuf = append(buf, '\"')\n", access), nil
	default:
		return "", fmt.Errorf("unsupported field kind for marshal: %s", f.GoName)
	}
}

func marshalSliceCode(f Field, access string) (string, error) {
	var elemWrite string
	switch f.ElemKind {
	case KindString:
		elemWrite = "\t\tbuf = append(buf, '\"')\n\t\tbuf = jsonrt.AppendJSONEscapedString(buf, item)\n\t\tbuf = append(buf, '\"')\n"
	case KindInt:
		elemWrite = "\t\tbuf = strconv.AppendInt(buf, int64(item), 10)\n"
	case KindFloat:
		elemWrite = "\t\tbuf = strconv.AppendFloat(buf, float64(item), 'f', -1, 64)\n"
	case KindBool:
		elemWrite = "\t\tbuf = strconv.AppendBool(buf, item)\n"
	case KindStruct:
		elemWrite = "\t\titemCopy := item\n\t\tbuf = itemCopy.AppendJSON(buf)\n"
	default:
		return "", fmt.Errorf("unsupported slice element kind for field %s", f.GoName)
	}

	var b strings.Builder
	fmt.Fprintf(&b, "\tbuf = append(buf, '[')\n")
	fmt.Fprintf(&b, "\tfor i, item := range %s {\n", access)
	b.WriteString("\t\tif i > 0 {\n\t\t\tbuf = append(buf, ',')\n\t\t}\n")
	b.WriteString(elemWrite)
	b.WriteString("\t}\n")
	b.WriteString("\tbuf = append(buf, ']')\n")
	return b.String(), nil
}

func marshalMapCode(f Field, access string) (string, error) {
	var valWrite string
	switch f.ElemKind {
	case KindString:
		valWrite = "\t\tbuf = append(buf, '\"')\n\t\tbuf = jsonrt.AppendJSONEscapedString(buf, val)\n\t\tbuf = append(buf, '\"')\n"
	case KindInt:
		valWrite = "\t\tbuf = strconv.AppendInt(buf, int64(val), 10)\n"
	case KindFloat:
		valWrite = "\t\tbuf = strconv.AppendFloat(buf, float64(val), 'f', -1, 64)\n"
	case KindBool:
		valWrite = "\t\tbuf = strconv.AppendBool(buf, val)\n"
	case KindStruct:
		valWrite = "\t\tvalCopy := val\n\t\tbuf = valCopy.AppendJSON(buf)\n"
	case KindTime:
		valWrite = "\t\tbuf = append(buf, '\"')\n\t\tbuf = append(buf, val.Format(\"2006-01-02T15:04:05Z07:00\")...)\n\t\tbuf = append(buf, '\"')\n"
	default:
		return "", fmt.Errorf("unsupported map value kind for field %s", f.GoName)
	}

	var b strings.Builder
	firstVar := "first" + f.GoName
	fmt.Fprintf(&b, "\tbuf = append(buf, '{')\n")
	fmt.Fprintf(&b, "\tvar %s bool\n", firstVar)
	fmt.Fprintf(&b, "\t%s = true\n", firstVar)
	fmt.Fprintf(&b, "\tfor key, val := range %s {\n", access)
	b.WriteString(fmt.Sprintf("\t\tif !%s {\n\t\t\tbuf = append(buf, ',')\n\t\t}\n", firstVar))
	b.WriteString(fmt.Sprintf("\t\t%s = false\n", firstVar))
	b.WriteString("\t\tbuf = append(buf, '\"')\n")
	b.WriteString("\t\tbuf = jsonrt.AppendJSONEscapedString(buf, key)\n")
	b.WriteString("\t\tbuf = append(buf, '\"', ':')\n")
	b.WriteString(valWrite)
	b.WriteString("\t}\n")
	b.WriteString("\tbuf = append(buf, '}')\n")
	return b.String(), nil
}

// generateUnmarshal produces two functions for the struct:
//   - ParseJSON(data []byte) bool: public entry, creates a new Parser.
//   - parseFromParser(p *jsonrt.Parser) bool: does the real parse,
//     continuing on an existing Parser. Nested structs call
//     parseFromParser on each other, avoiding SkipValue range
//     delimiting plus re-parsing from scratch with a new Parser —
//     validated ~44% faster and 40% fewer allocs (see proto_nested).
//
// The parser accepts ARBITRARY KEY ORDER, required for a general-purpose
// generator.
func generateUnmarshal(def StructDef) (string, error) {
	var b strings.Builder

	fmt.Fprintf(&b, "func (v *%s) ParseJSON(data []byte) bool {\n", def.Name)
	b.WriteString("\tp := jsonrt.NewParser(data)\n")
	b.WriteString("\treturn v.parseFromParser(p)\n")
	b.WriteString("}\n\n")

	fmt.Fprintf(&b, "func (v *%s) parseFromParser(p *jsonrt.Parser) bool {\n", def.Name)
	b.WriteString("\tif !p.ExpectByte('{') {\n\t\treturn false\n\t}\n")
	b.WriteString("\tif p.PeekByte('}') {\n\t\tp.Pos++\n\t\treturn true\n\t}\n")
	b.WriteString("\tfor {\n")
	b.WriteString("\t\tkey, ok := p.ParseKey()\n")
	b.WriteString("\t\tif !ok {\n\t\t\treturn false\n\t\t}\n")
	b.WriteString("\t\tswitch key {\n")

	for _, f := range def.Fields {
		fmt.Fprintf(&b, "\t\tcase %q:\n", f.JSONName)
		code, err := unmarshalFieldCode(f)
		if err != nil {
			return "", err
		}
		b.WriteString(code)
	}

	b.WriteString("\t\tdefault:\n\t\t\tif !p.SkipValue() {\n\t\t\t\treturn false\n\t\t\t}\n")
	b.WriteString("\t\t}\n")
	b.WriteString("\t\tif p.PeekByte(',') {\n\t\t\tp.Pos++\n\t\t\tcontinue\n\t\t}\n")
	b.WriteString("\t\tbreak\n")
	b.WriteString("\t}\n")
	b.WriteString("\treturn p.ExpectByte('}')\n")
	b.WriteString("}\n")
	return b.String(), nil
}

func unmarshalFieldCode(f Field) (string, error) {
	access := "v." + f.GoName
	switch f.Kind {
	case KindString:
		return fmt.Sprintf("\t\t\ts, ok := p.ParseString()\n\t\t\tif !ok {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\t%s = s\n", access), nil
	case KindInt:
		return fmt.Sprintf("\t\t\tn, ok := p.ParseInt()\n\t\t\tif !ok {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\t%s = int(n)\n", access), nil
	case KindFloat:
		return fmt.Sprintf("\t\t\tfl, ok := p.ParseFloat()\n\t\t\tif !ok {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\t%s = fl\n", access), nil
	case KindBool:
		return fmt.Sprintf("\t\t\tbl, ok := p.ParseBool()\n\t\t\tif !ok {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\t%s = bl\n", access), nil
	case KindStruct:
		// Call parseFromParser directly, continuing on the same
		// Parser — no SkipValue and no new Parser (see generateUnmarshal).
		return fmt.Sprintf("\t\t\tif !(&%s).parseFromParser(p) {\n\t\t\t\treturn false\n\t\t\t}\n", access), nil
	case KindStructPtr:
		structName := strings.TrimPrefix(f.TypeName, "*")
		return fmt.Sprintf("\t\t\tif p.PeekNull() {\n\t\t\t\tp.Pos += 4\n\t\t\t\t%s = nil\n\t\t\t} else {\n\t\t\t\tnewVal := &%s{}\n\t\t\t\tif !newVal.parseFromParser(p) {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\t%s = newVal\n\t\t\t}\n", access, structName, access), nil
	case KindSlice:
		return unmarshalSliceCode(f, access)
	case KindMap:
		return unmarshalMapCode(f, access)
	case KindTime:
		return fmt.Sprintf("\t\t\tts, ok := p.ParseString()\n\t\t\tif !ok {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\tt, err := time.Parse(time.RFC3339, ts)\n\t\t\tif err != nil {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\t%s = t\n", access), nil
	default:
		return "", fmt.Errorf("unsupported field kind for unmarshal: %s", f.GoName)
	}
}

func unmarshalSliceCode(f Field, access string) (string, error) {
	var parseElem string
	switch f.ElemKind {
	case KindString:
		parseElem = "\t\t\t\ts, ok := p.ParseString()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\t%s = append(%s, s)\n"
	case KindInt:
		parseElem = "\t\t\t\tn, ok := p.ParseInt()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\t%s = append(%s, int(n))\n"
	case KindFloat:
		parseElem = "\t\t\t\tfl, ok := p.ParseFloat()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\t%s = append(%s, fl)\n"
	case KindBool:
		parseElem = "\t\t\t\tbl, ok := p.ParseBool()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\t%s = append(%s, bl)\n"
	case KindStruct:
		parseElem = "\t\t\t\tvar elem " + f.ElemTypeName + "\n\t\t\t\tif !elem.parseFromParser(p) {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\t%s = append(%s, elem)\n"
	default:
		return "", fmt.Errorf("unsupported slice element kind")
	}

	var b strings.Builder
	b.WriteString("\t\t\tif !p.ExpectByte('[') {\n\t\t\t\treturn false\n\t\t\t}\n")
	b.WriteString("\t\t\tif !p.PeekByte(']') {\n")
	b.WriteString("\t\t\t\tfor {\n")
	fmt.Fprintf(&b, parseElem, access, access)
	b.WriteString("\t\t\t\t\tif p.PeekByte(',') {\n\t\t\t\t\t\tp.Pos++\n\t\t\t\t\t\tcontinue\n\t\t\t\t\t}\n")
	b.WriteString("\t\t\t\t\tbreak\n")
	b.WriteString("\t\t\t\t}\n")
	b.WriteString("\t\t\t}\n")
	b.WriteString("\t\t\tif !p.ExpectByte(']') {\n\t\t\t\treturn false\n\t\t\t}\n")
	return b.String(), nil
}

func unmarshalMapCode(f Field, access string) (string, error) {
	var parseVal string
	switch f.ElemKind {
	case KindString:
		parseVal = "\t\t\t\ts, ok := p.ParseString()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}"
	case KindInt:
		parseVal = "\t\t\t\tn, ok := p.ParseInt()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}"
	case KindFloat:
		parseVal = "\t\t\t\tfl, ok := p.ParseFloat()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}"
	case KindBool:
		parseVal = "\t\t\t\tbl, ok := p.ParseBool()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}"
	case KindStruct:
		parseVal = "\t\t\t\tvar valElem " + f.ElemTypeName + "\n\t\t\t\tif !valElem.parseFromParser(p) {\n\t\t\t\t\treturn false\n\t\t\t\t}"
	case KindTime:
		parseVal = "\t\t\t\tts, ok := p.ParseString()\n\t\t\t\tif !ok {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\tvalTime, err := time.Parse(time.RFC3339, ts)\n\t\t\t\tif err != nil {\n\t\t\t\t\treturn false\n\t\t\t\t}"
	default:
		return "", fmt.Errorf("unsupported map value kind")
	}

	var assign string
	switch f.ElemKind {
	case KindString:
		assign = "s"
	case KindInt:
		assign = "int(n)"
	case KindFloat:
		assign = "fl"
	case KindBool:
		assign = "bl"
	case KindStruct:
		assign = "valElem"
	case KindTime:
		assign = "valTime"
	}

	var b strings.Builder
	b.WriteString("\t\t\tif !p.ExpectByte('{') {\n\t\t\t\treturn false\n\t\t\t}\n")
	b.WriteString("\t\t\tif !p.PeekByte('}') {\n")
	b.WriteString("\t\t\t\tfor {\n")
	b.WriteString("\t\t\t\t\tkey, ok := p.ParseKey()\n")
	b.WriteString("\t\t\t\t\tif !ok {\n\t\t\t\t\t\treturn false\n\t\t\t\t\t}\n")
	fmt.Fprintf(&b, "%s\n", parseVal)
	fmt.Fprintf(&b, "\t\t\t\t\tif %s == nil {\n\t\t\t\t\t\t%s = make(%s)\n\t\t\t\t\t}\n", access, access, f.TypeName)
	fmt.Fprintf(&b, "\t\t\t\t\t%s[key] = %s\n", access, assign)
	b.WriteString("\t\t\t\t\tif p.PeekByte(',') {\n\t\t\t\t\t\tp.Pos++\n\t\t\t\t\t\tcontinue\n\t\t\t\t\t}\n")
	b.WriteString("\t\t\t\t\tbreak\n")
	b.WriteString("\t\t\t\t}\n")
	b.WriteString("\t\t\t}\n")
	b.WriteString("\t\t\tif !p.ExpectByte('}') {\n\t\t\t\treturn false\n\t\t\t}\n")
	return b.String(), nil
}
